method Strongest_Extension(class_name: string, extensions: seq<string>) returns (result: string)
    requires class_name != ""
    requires extensions != []
    ensures result == class_name + "." + strongestExtension
    ensures strongestExtension == extensions[strongestIndex]
    ensures strongestIndex in 0 ..| extensions
    ensures forall i :: 0 <= i < |extensions| ==> (if strength(extensions[i]) > strength(strongestExtension) then i > strongestIndex)
    ensures forall i :: 0 <= i < |extensions| && strength(extensions[i]) == strength(strongestExtension) ==> i <= strongestIndex
{
    var strongestIndex := 0;
    var strongestExtension := extensions[0];

    // Calculate the strength of the extensions and find the strongest one
    var maxStrength := strength(strongestExtension);
    var i := 0;

    while i < |extensions|
        invariant 0 <= i <= |extensions|
        invariant strongestExtension == extensions[strongestIndex]
        invariant maxStrength == strength(strongestExtension)
    {
        if strength(extensions[i]) > maxStrength {
            strongestIndex := i;
            strongestExtension := extensions[i];
            maxStrength := strength(strongestExtension);
        }
        i := i + 1;
    }

    return class_name + "." + strongestExtension;
}

function method strength(extension: string) : int
{
    var cap := 0;
    var sm := 0;
    var i := 0;

    while i < |extension|
        invariant 0 <= i <= |extension|
        invariant cap >= 0 && sm >= 0
    {
        if extension[i] >= 'A' && extension[i] <= 'Z' {
            cap := cap + 1;
        } else if extension[i] >= 'a' && extension[i] <= 'z' {
            sm := sm + 1;
        }
        i := i + 1;
    }

    return cap - sm;
}
